import React from 'react';
import './Menu.css';

// Import local images (create these files in your assets folder)
import koftaImage from '../assets/kofta.jpg';
import samosaImage from '../assets/samosa.jpg';
import roganJoshImage from '../assets/rogan-josh.jpg';

const Menu = () => {
  const menuItems = [
    {
      id: 1,
      name: 'Kofta',
      price: 250,
      description: "Soft, spicy koftas soaking in rich, creamy gravy — a bite of pure bliss in every spoonful.",
      image: koftaImage,
      veg: true
    },
    {
      id: 2,
      name: 'Samosa',
      price: 180,
      description: "Crispy outside, spicy inside — a samosa is not just a snack, it's an emotion wrapped in crunch.",
      image: samosaImage,
      veg: true
    },
    {
      id: 3,
      name: 'Rogan Josh',
      price: 280,
      description: 'Aromatic lamb curry from Kashmir with tender meat and rich spices',
      image: roganJoshImage,
      veg: false
    }
  ];

  return (
    <div className="menu-page">
      <div className="menu-header">
        <h1>Hotel Shyam Special Menu</h1>
        <p className="tagline">Authentic flavors crafted with traditional recipes</p>
      </div>

      <div className="menu-grid">
        {menuItems.map(item => (
          <div key={item.id} className="menu-card">
            <div className="image-container">
              <img src={item.image} alt={item.name} className="food-image" />
              <span className={`food-tag ${item.veg ? 'veg' : 'non-veg'}`}>
                {item.veg ? '🟢 VEG' : '🔴 NON-VEG'}
              </span>
            </div>
            <div className="card-body">
              <h3 className="dish-name">{item.name}</h3>
              <p className="dish-description">{item.description}</p>
              <div className="price-section">
                <span className="price">₹{item.price}</span>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Menu;
